def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Identify each distinct rectangular section of the 8-pattern by its
    # row/column runs. Color sections according to the guide's colors in
    # top-to-bottom, then left-to-right order.
    guide = [(r, c, grid[r][c])
             for r in range(h) for c in range(w)
             if grid[r][c] not in (0, 8)]
    colors = []
    for _, _, v in guide:
        if v not in colors:
            colors.append(v)
    if not colors:
        return out

    # Group 8 cells that form contiguous rectangles; diagonal touching does
    # not merge separate sections.
    unseen = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    parts = []
    while unseen:
        seed = min(unseen)
        stack = [seed]
        unseen.remove(seed)
        comp = []
        while stack:
            r, c = stack.pop()
            comp.append((r, c))
            for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
                if (nr, nc) in unseen:
                    unseen.remove((nr, nc))
                    stack.append((nr, nc))
        parts.append(comp)

    parts.sort(key=lambda p: (min(r for r,c in p), min(c for r,c in p)))
    for i, part in enumerate(parts):
        color = colors[min(i, len(colors)-1)]
        for r, c in part:
            out[r][c] = color
    return out
