def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    occupied_rows = [r for r in range(h) if 8 in grid[r]]
    if not occupied_rows:
        return out

    # The guide identifies the colors for successive horizontal sections
    # of the large pattern, in top-to-bottom order.
    guide = [(r, c, grid[r][c])
             for r in range(h) for c in range(w)
             if grid[r][c] not in (0, 8)]
    guide_colors = []
    for r, c, color in sorted(guide):
        if color not in guide_colors:
            guide_colors.append(color)

    bands = []
    for r in occupied_rows:
        if not bands or r > bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)

    colors = guide_colors or [1]
    for i, rows in enumerate(bands):
        color = colors[min(i, len(colors) - 1)]
        for r in rows:
            for c in range(w):
                if grid[r][c] == 8:
                    out[r][c] = color
    return out
